// DSI_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module DSI_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [2:0] c_cmd_op,
  input logic [5:0] c_cmd_dt,
  input logic [7:0] c_cmd_dcs,
  input logic [15:0] c_cmd_len,
  input logic [15:0] c_cmd_len2,
  input logic  c_cmd_valid,
  input logic  c_cmd_busy,
  input logic  c_tx_oe,
  input logic [15:0] c_pkt_cnt,
  input logic [23:0] c_bta_data,
  input logic  c_bta_done,
  input logic  c_irq,
  input logic  c_pl_we,
  input logic [7:0] c_pl_wdata
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 42;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:41];          // model of every stored word
  logic [1:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_GO;

  always_comb begin
    m_set = '0;
    if (c_bta_done) m_set[0] = 1'b1;
    if (c_irq) m_set[1] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_w[21] <= 32'h0;
      m_w[22] <= 32'h0;
      m_w[23] <= 32'h0;
      m_w[24] <= 32'h0;
      m_w[25] <= 32'h0;
      m_w[26] <= 32'h0;
      m_w[27] <= 32'h0;
      m_w[28] <= 32'h0;
      m_w[29] <= 32'h0;
      m_w[30] <= 32'h0;
      m_w[31] <= 32'h0;
      m_w[32] <= 32'h0;
      m_w[33] <= 32'h0;
      m_w[34] <= 32'h0;
      m_w[35] <= 32'h0;
      m_w[36] <= 32'h0;
      m_w[37] <= 32'h0;
      m_w[38] <= 32'h0;
      m_w[39] <= 32'h0;
      m_w[40] <= 32'h0;
      m_w[41] <= 32'h0;
      m_pulse_GO <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h3;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h1FFFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      m_pulse_GO <= (m_wr && m_map && m_idx == 7) ? PWDATA & m_be & 32'h1 : 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h44530200;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return 0;
      8: return 0;
      9: return 0;
      10: return 0;
      11: return 0;
      12: return 0;
      13: return 0;
      14: return 0;
      15: return 0;
      16: return 0;
      17: return 0;
      18: return 0;
      19: return 0;
      20: return 0;
      21: return 0;
      22: return 0;
      23: return 0;
      24: return 0;
      25: return 0;
      26: return 0;
      27: return 0;
      28: return 0;
      29: return 0;
      30: return 0;
      31: return 0;
      32: return 0;
      33: return 0;
      34: return 0;
      35: return 0;
      36: return 0;
      37: return 0;
      38: return 0;
      39: return 0;
      40: return (32'(c_cmd_busy) << 0) | (32'(c_tx_oe) << 1) | (32'(c_pkt_cnt) << 2);
      41: return (32'(c_bta_data) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  wire        m_bus_partial = PWRITE && PSTRB != 4'hF && m_map && (m_idx == 8 || m_idx == 9 || m_idx == 10 || m_idx == 11 || m_idx == 12 || m_idx == 13 || m_idx == 14 || m_idx == 15 || m_idx == 16 || m_idx == 17 || m_idx == 18 || m_idx == 19 || m_idx == 20 || m_idx == 21 || m_idx == 22 || m_idx == 23 || m_idx == 24 || m_idx == 25 || m_idx == 26 || m_idx == 27 || m_idx == 28 || m_idx == 29 || m_idx == 30 || m_idx == 31 || m_idx == 32 || m_idx == 33 || m_idx == 34 || m_idx == 35 || m_idx == 36 || m_idx == 37 || m_idx == 38 || m_idx == 39);   // dropped with PSLVERR
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == (!m_map || m_bus_partial))
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][1:0] & m_w[2][1:0]))
  `SVA_INV(a_core_cmd_op, c_cmd_op == m_w[5][2:0])
  `SVA_INV(a_core_cmd_dt, c_cmd_dt == m_w[5][8:3])
  `SVA_INV(a_core_cmd_dcs, c_cmd_dcs == m_w[5][16:9])
  `SVA_INV(a_core_cmd_len, c_cmd_len == m_w[6][15:0])
  `SVA_INV(a_core_cmd_len2, c_cmd_len2 == m_w[6][31:16])
  `SVA_INV(a_core_cmd_valid, c_cmd_valid == m_pulse_GO[0])
  wire m_bus_wr_PAYLOAD = m_wr && m_map && PSTRB == 4'hF && (m_idx == 8 || m_idx == 9 || m_idx == 10 || m_idx == 11 || m_idx == 12 || m_idx == 13 || m_idx == 14 || m_idx == 15 || m_idx == 16 || m_idx == 17 || m_idx == 18 || m_idx == 19 || m_idx == 20 || m_idx == 21 || m_idx == 22 || m_idx == 23 || m_idx == 24 || m_idx == 25 || m_idx == 26 || m_idx == 27 || m_idx == 28 || m_idx == 29 || m_idx == 30 || m_idx == 31 || m_idx == 32 || m_idx == 33 || m_idx == 34 || m_idx == 35 || m_idx == 36 || m_idx == 37 || m_idx == 38 || m_idx == 39);
  `SVA_INV(a_core_pl_we, c_pl_we == m_bus_wr_PAYLOAD)
  `SVA_IMP(a_core_pl_addr_pl_wdata, m_bus_wr_PAYLOAD, int'(u_core.pl_addr) == (m_idx == 8 ? 0 : m_idx == 9 ? 1 : m_idx == 10 ? 2 : m_idx == 11 ? 3 : m_idx == 12 ? 4 : m_idx == 13 ? 5 : m_idx == 14 ? 6 : m_idx == 15 ? 7 : m_idx == 16 ? 8 : m_idx == 17 ? 9 : m_idx == 18 ? 10 : m_idx == 19 ? 11 : m_idx == 20 ? 12 : m_idx == 21 ? 13 : m_idx == 22 ? 14 : m_idx == 23 ? 15 : m_idx == 24 ? 16 : m_idx == 25 ? 17 : m_idx == 26 ? 18 : m_idx == 27 ? 19 : m_idx == 28 ? 20 : m_idx == 29 ? 21 : m_idx == 30 ? 22 : m_idx == 31 ? 23 : m_idx == 32 ? 24 : m_idx == 33 ? 25 : m_idx == 34 ? 26 : m_idx == 35 ? 27 : m_idx == 36 ? 28 : m_idx == 37 ? 29 : m_idx == 38 ? 30 : m_idx == 39 ? 31 : 0) && c_pl_wdata == PWDATA[7:0])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cmd_op == 3'h0 && c_cmd_dt == 6'h0 && c_cmd_dcs == 8'h0 && c_cmd_len == 16'h0 && c_cmd_len2 == 16'h0 && c_cmd_valid == 1'h0 && !c_pl_we)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CMD, m_rd && m_map && m_idx == 5)
  `FC(wr_CMD, m_wr && m_map && m_idx == 5)
  `FC(rd_LEN, m_rd && m_map && m_idx == 6)
  `FC(wr_LEN, m_wr && m_map && m_idx == 6)
  `FC(rd_GO, m_rd && m_map && m_idx == 7)
  `FC(wr_GO, m_wr && m_map && m_idx == 7)
  `FC(rd_PL0, m_rd && m_map && m_idx == 8)
  `FC(wr_PL0, m_wr && m_map && m_idx == 8)
  `FC(rd_PL1, m_rd && m_map && m_idx == 9)
  `FC(wr_PL1, m_wr && m_map && m_idx == 9)
  `FC(rd_PL2, m_rd && m_map && m_idx == 10)
  `FC(wr_PL2, m_wr && m_map && m_idx == 10)
  `FC(rd_PL3, m_rd && m_map && m_idx == 11)
  `FC(wr_PL3, m_wr && m_map && m_idx == 11)
  `FC(rd_PL4, m_rd && m_map && m_idx == 12)
  `FC(wr_PL4, m_wr && m_map && m_idx == 12)
  `FC(rd_PL5, m_rd && m_map && m_idx == 13)
  `FC(wr_PL5, m_wr && m_map && m_idx == 13)
  `FC(rd_PL6, m_rd && m_map && m_idx == 14)
  `FC(wr_PL6, m_wr && m_map && m_idx == 14)
  `FC(rd_PL7, m_rd && m_map && m_idx == 15)
  `FC(wr_PL7, m_wr && m_map && m_idx == 15)
  `FC(rd_PL8, m_rd && m_map && m_idx == 16)
  `FC(wr_PL8, m_wr && m_map && m_idx == 16)
  `FC(rd_PL9, m_rd && m_map && m_idx == 17)
  `FC(wr_PL9, m_wr && m_map && m_idx == 17)
  `FC(rd_PL10, m_rd && m_map && m_idx == 18)
  `FC(wr_PL10, m_wr && m_map && m_idx == 18)
  `FC(rd_PL11, m_rd && m_map && m_idx == 19)
  `FC(wr_PL11, m_wr && m_map && m_idx == 19)
  `FC(rd_PL12, m_rd && m_map && m_idx == 20)
  `FC(wr_PL12, m_wr && m_map && m_idx == 20)
  `FC(rd_PL13, m_rd && m_map && m_idx == 21)
  `FC(wr_PL13, m_wr && m_map && m_idx == 21)
  `FC(rd_PL14, m_rd && m_map && m_idx == 22)
  `FC(wr_PL14, m_wr && m_map && m_idx == 22)
  `FC(rd_PL15, m_rd && m_map && m_idx == 23)
  `FC(wr_PL15, m_wr && m_map && m_idx == 23)
  `FC(rd_PL16, m_rd && m_map && m_idx == 24)
  `FC(wr_PL16, m_wr && m_map && m_idx == 24)
  `FC(rd_PL17, m_rd && m_map && m_idx == 25)
  `FC(wr_PL17, m_wr && m_map && m_idx == 25)
  `FC(rd_PL18, m_rd && m_map && m_idx == 26)
  `FC(wr_PL18, m_wr && m_map && m_idx == 26)
  `FC(rd_PL19, m_rd && m_map && m_idx == 27)
  `FC(wr_PL19, m_wr && m_map && m_idx == 27)
  `FC(rd_PL20, m_rd && m_map && m_idx == 28)
  `FC(wr_PL20, m_wr && m_map && m_idx == 28)
  `FC(rd_PL21, m_rd && m_map && m_idx == 29)
  `FC(wr_PL21, m_wr && m_map && m_idx == 29)
  `FC(rd_PL22, m_rd && m_map && m_idx == 30)
  `FC(wr_PL22, m_wr && m_map && m_idx == 30)
  `FC(rd_PL23, m_rd && m_map && m_idx == 31)
  `FC(wr_PL23, m_wr && m_map && m_idx == 31)
  `FC(rd_PL24, m_rd && m_map && m_idx == 32)
  `FC(wr_PL24, m_wr && m_map && m_idx == 32)
  `FC(rd_PL25, m_rd && m_map && m_idx == 33)
  `FC(wr_PL25, m_wr && m_map && m_idx == 33)
  `FC(rd_PL26, m_rd && m_map && m_idx == 34)
  `FC(wr_PL26, m_wr && m_map && m_idx == 34)
  `FC(rd_PL27, m_rd && m_map && m_idx == 35)
  `FC(wr_PL27, m_wr && m_map && m_idx == 35)
  `FC(rd_PL28, m_rd && m_map && m_idx == 36)
  `FC(wr_PL28, m_wr && m_map && m_idx == 36)
  `FC(rd_PL29, m_rd && m_map && m_idx == 37)
  `FC(wr_PL29, m_wr && m_map && m_idx == 37)
  `FC(rd_PL30, m_rd && m_map && m_idx == 38)
  `FC(wr_PL30, m_wr && m_map && m_idx == 38)
  `FC(rd_PL31, m_rd && m_map && m_idx == 39)
  `FC(wr_PL31, m_wr && m_map && m_idx == 39)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 40)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 40)
  `FC(rd_BTA, m_rd && m_map && m_idx == 41)
  `FC(wr_BTA, m_wr && m_map && m_idx == 41)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_BTA_DONE_set, m_set[0])
  `FC(irq_BTA_DONE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_BTA_DONE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_BTA_DONE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_ERROR_set, m_set[1])
  `FC(irq_ERROR_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_ERROR_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_ERROR_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(cmd_cmd_valid, m_pulse_GO[0])
  `FC(core_register_partial_write, m_wr && m_bus_partial)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind DSI_apb DSI_apb_sva u_apb_sva (.*);
